import {createSiteShell} from './site-shell.js?v=40';
import {createNetwork} from './network-ui.js?v=40';
import {legacyNetworkRoute} from './network-engine.js?v=40';
import {HOME_POST_IDS,HISTORY_TOPICS,searchGuidance,searchableEntry,searchArchive,isPostDiscovered,discoverSearchResults,hintMarkup} from './investigation.js?v=40';
import {watchOriginalReading} from './original-reading.js?v=40';
import {createDwellCollector} from './auto-read.js?v=40';
import {classicPost,classicThread} from './forum-ui.js?v=40';
import {createImmersion} from './immersion.js?v=40';
import {archiveDocs,archiveChapters} from './expansion-content.js?v=40';
import {createArchive} from './expansion-ui.js?v=40';
import {SAVE_KEY,CLUES,OPENING_DOC_CLUES,recordOpeningDocument,freshState,parseSave,addClue,searchItems,judgeDeduction,progress,canReadDoc,GAME_ACCOUNTS,CASE_REQUIREMENTS,canUseAccount,checkAccountLogin,unlockCaseFolder,completeCaseStep,chooseCaseEnding,escapeHTML as esc} from './engine.js?v=40';
import {intro,people,posts,docs,chats,searchIndex} from './content.js?v=40';
import {campaignChapters,caseDocs,casePeople,casePosts,caseEndings,caseHints} from './campaign.js?v=40';
Object.assign(people,casePeople);
let caseOrder=['taste','shower','pickup','mix'];
const $=s=>document.querySelector(s);
let state=freshState(), storageAvailable=true;
try{state=parseSave(localStorage.getItem(SAVE_KEY));}catch{storageAvailable=false;}
let lastBase='#forum',currentFilter='all',toastTimer,introStep=0,zoom=100;
const view=$('#view'),reader=$('#reader'),story=$('#story');
const archive=createArchive({getState:()=>state,save,view,heading,esc,toast,showReader,render});
const immersion=createImmersion({getState:()=>state,clues:CLUES,archiveDocs,chapters:campaignChapters,archiveChapters,view,toast});
const autoRead=createDwellCollector();
const siteShell=createSiteShell({getState:()=>state,save,navigate:openApp,toast});
const network=createNetwork({getState:()=>state,save,view,collect,archive,toast,render,entered:()=>enteredComputer});
function scheduleOriginalRead(section,id){
 const isAttachment=section==='doc'||section==='casefile';let remember,stillAllowed=()=>true;
 if(section==='doc'&&Object.hasOwn(OPENING_DOC_CLUES,id)&&canReadDoc(state,id))remember=()=>collect(OPENING_DOC_CLUES[id],true);
 else if(section==='casefile'){const d=caseDocs[id];if(d?.clue&&canAccessCaseDoc(d)){remember=()=>saveCaseDoc(id,true);stillAllowed=()=>canAccessCaseDoc(d);}}
 else if(section==='post'){const p=getVisiblePosts().find(p=>p.id===id);if(p?.clue&&isPostDiscovered(state,id))remember=()=>collect(p.clue,true);}
 else if(section==='chat'||section==='chats'){const c=chats[id]||chats.azhe;if(c.clue)remember=()=>collect(c.clue,true);}
 if(!remember||isAttachment&&!reader.open)return;
 const content=isAttachment?$('#readerBody'):view,existing=content.querySelector('[data-auto-read-status]');existing?.remove();
 const hint=document.createElement('p');hint.className='small-text auto-read-hint';hint.dataset.autoReadStatus='';hint.setAttribute('role','status');hint.textContent='阅读片刻后会自动收入调查本，也可立即保存。';content.prepend(hint);
 watchOriginalReading({collector:autoRead,state,getState:()=>state,hash:location.hash||'#forum',getHash:()=>location.hash||'#forum',entered:()=>enteredComputer,computer:$('#computer'),appWindow:$('#appWindow'),reader:isAttachment?reader:null,document,image:isAttachment?$('#reportImage'):null,collect:remember,status:hint,stillAllowed});
}
document.addEventListener('visibilitychange',()=>autoRead.refresh());
document.addEventListener('close',()=>autoRead.refresh(),true);
document.addEventListener('click',()=>queueMicrotask(()=>autoRead.refresh()));
window.addEventListener('focus',()=>autoRead.refresh());
window.addEventListener('blur',()=>autoRead.refresh());

function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));storageAvailable=true;}catch{storageAvailable=false;}updateChrome();}
function updateChrome(){const p=state.finished?[true,state.caseStage>=4,state.caseSolved]:progress(state);document.querySelectorAll('.case-marks i').forEach((e,i)=>e.classList.toggle('done',p[i]));$('#navCount').textContent=state.clues.length+state.expansion.evidence.length;$('#caseStatus').textContent=archive.status()||(state.caseSolved?'案件已查清 · 可以回看结局':state.finished?'第'+(state.caseStage+4)+'章 · '+campaignChapters[state.caseStage].title:state.deduced?'再问问益达那次的事':state.clues.includes('source')?'阿哲也不认识第三个人':'第三个人，会是谁？');$('#saveStatus').textContent=storageAvailable?'● 进度保存在本机':'○ 本次进度暂不能保存';$('#saveStatus').title=storageAvailable?'刷新页面后可以继续。存档仅保存在当前浏览器。':'浏览器存储不可用，关闭页面后进度可能丢失。';const account=$('#accountButton');if(account){account.textContent=people[state.activeAccount]?.name||'by';account.title='账号登录与资料柜';}syncCover();immersion.sync();}

function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast')?.classList.remove('show'),3200);}
function markRead(id){if(!state.read.includes(id)){state.read.push(id);save();}}
function clueButton(id,label){return `<button class="collect-button ${state.clues.includes(id)?'collected':''}" data-collect="${id}">${state.clues.includes(id)?'✓ 已记入调查笔记':label||'＋ 记入调查笔记'}</button>`;}
function collect(id,automatic=false){const opening=Object.entries(OPENING_DOC_CLUES).find(([,clue])=>clue===id);const changed=opening?recordOpeningDocument(state,opening[0]):addClue(state,id);if(changed){save();toast((automatic?'已自动收入调查本：':'已记下：')+CLUES[id].title);}document.querySelectorAll(`[data-collect="${id}"]`).forEach(e=>{e.textContent='✓ 已记入调查笔记';e.classList.add('collected');});return changed;}
function avatar(id,size=''){const p=people[id];let slot=p?.slot;if(slot===undefined)slot=[...String(id)].reduce((a,c)=>a+c.charCodeAt(0),0)%6;return `<span class="avatar avatar-image ${size}" role="img" aria-label="${esc(p?.name||'用户')}的头像" style="--avatar-pos:${[0,50,100][slot%3]}% ${slot<3?0:100}%"></span>`;}

function heading(kicker,title,sub=''){return `<div class="page-title"><div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div></div>`;}

function searchForm(query=''){return `<form class="search-form" data-search><span class="search-icon" aria-hidden="true">⌕</span><input name="q" type="search" value="${esc(query)}" placeholder="搜索帖子、昵称，或者一句记得的话…" aria-label="搜索帖子、人物与资料" autocomplete="off" maxlength="120" list="searchWords"><datalist id="searchWords"></datalist><button type="submit">搜索</button></form>`;}
const campusArt=`<svg class="campus-art" viewBox="0 0 310 125" aria-hidden="true"><g fill="none" stroke="#9caa82" stroke-width="1.2"><path d="M4 113h298M25 108V46h82v62M100 108V30h119v78M214 108V57h63v51M17 46h98M94 30h132M208 57h76M132 30V13h53v17M125 13h68M151 13V7h13v6"/><path d="M34 55h15v17H34zm26 0h15v17H60zm26 0h12v17H86zM34 81h15v17H34zm26 0h15v17H60zm26 0h12v17H86zM113 43h17v18h-17zm29 0h17v18h-17zm29 0h17v18h-17zm29 0h9v18h-9zM113 72h17v17h-17zm58 0h17v17h-17zm29 0h9v17h-9zM145 79h14v29h-14zM228 69h14v16h-14zm24 0h14v16h-14zM228 94h14v14h-14zm24 0h14v14h-14z"/><circle cx="270" cy="25" r="13" stroke-dasharray="2 3"/><path d="M7 111V86m-6 11 6-18 8 18M290 110V85m-8 9 9-24 10 24M123 112l22-4h14l23 4"/></g><text x="158" y="25" text-anchor="middle" font-size="5" fill="#899972" letter-spacing="3">青禾高中</text></svg>`;
function threadCard(p){return classicThread(p,{people,avatar,esc,read:state.read,finished:state.finished});}

function renderBaseForum(){const all=getVisiblePosts().filter(p=>HOME_POST_IDS.includes(p.id));const shown=all.filter(p=>currentFilter==='all'||p.category===currentFilter);view.innerHTML=`<section class="forum-hero"><div class="forum-hero-inner"><span class="forum-emblem" aria-hidden="true">禾</span><div><h1>青禾论坛</h1><p>青禾高中学生交流社区</p></div></div><div class="forum-version"><strong>高三专区</strong><span>学习 · 食堂 · 宿舍 · 闲聊</span></div></section><section class="forum-tools">${searchForm()}<div class="forum-account"><a href="#profile/by">${avatar('by')}</a><span><a href="#profile/by"><strong>by</strong></a><small><a href="#files">我的资料</a>　<a href="#notes">我的笔记</a></small></span></div></section><p class="search-archive-note">这里只保留近期主题。较早的帖子请用搜索查找，可以输入记得的一件事。</p><section class="forum-board"><div class="notice-strip"><span aria-hidden="true">♧</span><span><a href="#post/notice">论坛使用说明</a>　｜　旧帖已归档，搜索仍可查阅。</span></div><div class="tabs" role="group" aria-label="帖子分类">${[['all','全部',all.length],['life','校园生活',all.filter(p=>p.category==='life').length],['study','学习互助',all.filter(p=>p.category==='study').length],['notice','站务',1]].map(([id,t,n])=>`<button class="tab ${currentFilter===id?'active':''}" data-filter="${id}" aria-pressed="${currentFilter===id}">${t}<span class="tab-count">${n}</span></button>`).join('')}</div><div class="list-heading"><span>主题 / 标题</span><span>作者 / 发表</span><span>回复 / 浏览</span></div><div class="topic-list">${shown.map(threadCard).join('')}</div><div class="board-footer"><span>共 ${shown.length} 个主题</span><span class="board-page" aria-label="第1页">1</span></div></section><div class="forum-status">当前登录：by <a href="${state.finished?'#end':'#post/reports'}">${state.finished?'阅读第一幕尾声':'最近查看：三份检查报告'} →</a></div>`;}

function renderPost(id){const p=getVisiblePosts().find(x=>x.id===id);if(!p)return missing();if(!isPostDiscovered(state,id)){view.innerHTML=heading('','历史主题已归档','旧链接不能直接载入正文。试着搜索你记得的那件事。')+searchForm();return;}markRead('post:'+id);const replies=[...p.comments];if(id==='reports'&&state.finished)replies.push({name:'早睡观察员',avatar:'观',time:'03-24 12:37',text:state.caseStage>=6?'[作者已撤回此回复]':'不是有个人比楼主说的那两个还早拉肚子吗，他自己本子里都记了。怎么不问问他，光在这猜一起吃了什么。',suspect:true});if(id==='reports'&&state.caseStage>=2)replies.push({name:'早睡观察员',time:'03-25 12:36',text:state.caseStage>=6?'[作者已撤回此回复] <a href="#casefile/quote">查看先前留存的引用</a>':'不是说两页复印件都夹在语文卷最后面了吗，拿出来看日期就知道了。老绕着吃面说干什么。',suspect:true});view.innerHTML=classicPost({post:p,replies,people,avatar,esc,clueButton,actions:immersion.floorActions});}

function renderBaseFiles(){view.innerHTML=heading('','我的资料','检查报告、借来的笔记，还有几张存下来的图片。')+`<div class="page-grid">${Object.values(docs).filter(d=>canReadDoc(state,d.id)).map(d=>`<a class="file-card" href="#doc/${d.id}">${!state.read.includes('doc:'+d.id)?'<span class="file-new">未读</span>':''}<span class="file-icon">${d.code}</span><h2>${d.title}</h2><p>${d.subtitle}</p><small>${d.source}<span style="float:right">打开 →</span></small></a>`).join('')}</div>`;}

function renderChat(id='azhe'){if(!chats[id])id='azhe';const c=chats[id];markRead('chat:'+id);view.innerHTML=heading('','对话记录','周末的聊天，以及回学校后说过的话。')+`<div class="chat-layout"><nav class="chat-list" aria-label="对话人物">${Object.entries(chats).map(([key,x])=>`<a class="chat-person ${key===id?'active':''}" href="#chat/${key}">${avatar(key)}<span><strong>${x.name}</strong><small>${x.preview}</small></span></a>`).join('')}</nav><section class="chat-main"><header class="chat-header"><h2>${c.name}</h2><small>${c.context}</small></header><div class="chat-messages"><p class="chat-context">${c.context.split(' · ')[0]}</p>${c.messages.map(([person,text])=>`<div class="chat-line ${person==='by'?'mine':''}">${avatar(person)}<div class="bubble">${esc(text)}</div></div>`).join('')}</div><div class="chat-next">${c.next}${c.clue?'<br>'+clueButton(c.clue,id==='azhe'?'＋ 记下投稿来源的说明':'＋ 记下这段委托'):''}</div></section></div>`;}
function renderBaseNotes(){const list=state.clues.map(id=>CLUES[id]);view.innerHTML=heading('YOUR INVESTIGATION','调查笔记','先记在这里，想不起来的时候再翻。')+(state.deduced?`<div class="completed-card"><h2>第三张的事，先记到这里。</h2><p>阿哲也不知道最后那张是谁的。再问问益达，看看他前面那次是怎么回事。</p><a href="#end">${state.finished?'重读第一幕尾声':'继续故事：益达的那两页记录'} →</a></div>`:'')+(list.length?`<div class="note-grid">${list.map(c=>`<article class="evidence-note"><small>${c.code} / 已记下</small><h2>${c.title}</h2><p>${c.text}</p><a href="${c.route}">再看一遍 ↗</a></article>`).join('')}</div>`:`<div class="empty-panel">还没记什么。<br>先读一读<a href="#post/reports">有三张报告的帖子</a>，看完可以把它记下来。</div>`)+`<div class="notebook-actions"><a class="primary" href="#deduction">整理一次判断 <span>→</span></a><span class="small-text">有几件事还没问清楚，先想想现在知道了什么。</span></div>`;}
function renderDeduction(){view.innerHTML=heading('PUT THE PIECES TOGETHER','先别急着认人','第一幕 · 整理笔记')+`<section class="deduction-panel"><h2>现在，能确认第三位投稿者是谁吗？</h2><p>论坛里已有“同宿舍”“同一顿夜宵”的说法。这些话里，哪些是你亲眼看过、亲口问过的？</p>${state.deduced?'<div class="completed-card"><p>你已经完成这次核对，仍可重新选择依据。</p><a href="#end">继续故事 →</a></div>':''}<form id="deductionForm"><span class="deduction-label">01 / 选两条支持你判断的线索</span>${state.clues.length?`<div class="evidence-options">${state.clues.map(id=>`<label class="evidence-option"><input type="checkbox" name="evidence" value="${id}"><span>${CLUES[id].title}<small>${CLUES[id].text}</small></span></label>`).join('')}</div>`:`<div class="empty-panel">还没有收进笔记的材料。<a href="#post/reports">读原帖</a>，再<a href="#chat/azhe">问阿哲</a>，阅读片刻即可自动记入笔记，也可以立即点保存。</div>`}<span class="deduction-label">02 / 你的判断</span><label class="conclusion"><input type="radio" name="conclusion" value="yida" required><span>益达更早腹泻，所以第三份应该是他的。</span></label><label class="conclusion"><input type="radio" name="conclusion" value="meal"><span>三份报告同时出现，所以可以确认与同一次夜宵有关。</span></label><label class="conclusion"><input type="radio" name="conclusion" value="unverified"><span>还不能确认。阿哲不认识第三个人，现在还不知道这张报告是谁的。</span></label><div class="deduction-feedback" id="deductionFeedback" role="status"></div><div class="deduction-bottom"><button class="primary" type="submit">记下这个判断 <span>→</span></button><a class="small-text" href="#notes">再翻翻笔记 ↗</a></div></form></section>`;}
function renderProfile(id){const p=people[id];if(!p)return missing();view.innerHTML=`<a class="back-link" href="#forum">← 返回论坛</a>${heading('','个人资料')}<section class="profile-header">${avatar(id)}<div><h1>${p.name}</h1><p>@${p.handle}<br>${p.bio}</p></div></section><div class="profile-links">${p.links.map(([t,r])=>`<a class="profile-link" href="${r}">${t}<span>↗</span></a>`).join('')}</div><p class="small-text" style="padding:15px 0"></p>`;}
function renderSearch(query){const guide=searchArchive(query,getSearchIndex(),searchItems),results=guide.results;if(discoverSearchResults(state,results))save();const suggestions=guide.suggestions.length?guide.suggestions:results.length?[]:['夜宵账单','周测作文','打印委托','旧照片'];view.innerHTML=heading('','搜索归档','按记得的人、事或一句话查找。归档只返回相关主题。')+searchForm(query)+(guide.corrected?`<p class="search-correction" role="status">已按“${esc(guide.query)}”检索（原输入：${esc(query)}）。</p>`:'')+`<p class="search-summary">${query?`“<strong>${esc(guide.query)}</strong>” · ${results.length} 项结果`:'输入一个从材料中记下的词。'}</p>`+(results.length?results.map(x=>`<a class="search-result" href="${x.route}"><span class="result-type">${x.type}</span><h2>${esc(x.title)}</h2><p>${esc(x.summary)}</p></a>`).join(''):'<div class="empty-panel">没有找到相关记录。可以换成事件名称，或少写几个字。</div>')+(query&&suggestions.length?`<div class="search-hints"><span>相关说法：</span>${suggestions.map(term=>`<button data-query="${esc(term)}">${esc(term)}</button>`).join('')}</div>`:'');}
function renderEnding(){if(!state.deduced){renderDeduction();return;}if(!state.finished){state.finished=true;save();}view.innerHTML=heading('','那条新回复','3月24日，星期一 · 午休')+`<article class="deduction-panel"><div class="ending-scene"><p>你在纸上写了句“第三个人还不知道是谁”，想了一会儿，又在旁边加了个问号。</p><p>课间你还是去找了益达。他听见你问拉肚子的事，脸上的笑一下没了。你解释了半天，他才从桌洞里抽出本子，翻到那两页，拍在你面前。</p><p>“看吧。我去查过，没查出来。你要是不信，周末我把报告也拿过来。”</p><p>你没接这句话，低头看本子。他那次不舒服记在3月11日，比你周测那天早了三天。再往前一页，是你早上没带纸、最后用了花洒那件事。边上歪歪扭扭一行字：<b>你最好是真的没听见。</b></p><p>确实是你自己的字。中午回来你把这事讲给全宿舍听，杰哥笑了半天，你还抢过益达的笔补了这一句。刚才怎么连这个都忘了。</p><p>午休时，陈叙问你在翻什么。你把本子摊给他看，说益达之前也拉过肚子，但他又说查过了没有。陈叙看了一会儿，让你先别跟益达吵，等周末拿到报告再说。</p><p>十二点四十左右，阿哲从办公室出来，在走廊叫住你。他刚用电脑看了眼论坛，帖子底下多了一条回复：</p><div class="block-quote">“不是有个人比楼主说的那两个还早拉肚子吗，他自己本子里都记了。怎么不问问他，光在这猜一起吃了什么。”<br><small>早睡观察员 · 03-24 12:37</small></div><p>你第一反应是益达把本子给别人看了。回教室问他，他说没有，今天除了你，没人借过。</p><p>你又把原帖想了一遍。里面有报告，有吃面那点传话，<b>可从头到尾，没人提过益达的本子。</b></p><p>这个“早睡观察员”，是从哪儿知道的？</p></div><div class="ending-tag">第一幕结束</div><p>本子的事还没问清。杰哥那晚从食堂带回来的夜宵，也该重新看一遍。</p><div class="ending-actions"><a class="primary" href="#chapter/4">继续：食堂关门以后 →</a></div><div class="ending-actions"><a class="primary" href="#post/reports">去看那条回复</a><a class="secondary" href="#notes">翻翻笔记</a></div></article>`;}

function missing(){view.innerHTML=heading('NOT FOUND','这里没有这份资料','链接可能不完整。已经看过的资料，仍可以从索引找回。')+'<a class="primary" href="#forum">回校园论坛 →</a>';}
let enteredComputer=false, windowMaximized=false;
const routeTrail=[];
function syncCover(){const hasSave=state.introDone||state.clues.length>0||state.read.length>0;$('#coverContinue').disabled=!hasSave;$('#continueDescription').textContent=hasSave?(state.caseSolved?'案件已完成，可重读结局与寻找彩蛋。':state.finished?'已到第'+(state.caseStage+4)+'章，已保留 '+state.clues.length+' 条线索。':`已保留 ${state.clues.length} 条线索，接着看。`):'还没有留下调查记录。';$('#coverStart strong').textContent=state.introDone?'重读开场':'开始游戏';}

function enterComputer(replay=false){enteredComputer=true;$('#cover').hidden=true;$('#computer').hidden=false;$('#computer').inert=false;document.body.classList.remove('cover-visible');openApp();if(replay||!state.introDone)showIntro();}
function showCover(){if(reader.open)reader.close();if(story.open)story.close();syncCover();$('#computer').hidden=true;$('#computer').inert=true;$('#cover').hidden=false;document.body.classList.add('cover-visible');$('#coverContinue').focus();}
function openApp(route){$('#appWindow').hidden=false;$('#taskApp').classList.add('active');if(route&&location.hash!==route)location.hash=route;else if(!route&&location.hash.startsWith('#doc/'))render();}
function minimizeApp(){$('#appWindow').hidden=true;$('#taskApp').classList.remove('active');$('#taskApp').focus();}
function syncWindow(section){const names={annex:'后续调查',archive:'资料副本',recover:'找回阅览账号','staff-login':'授权账号登录',mailbox:'校园邮箱 · 本地副本',vault:'加密附件',board:'证据连线',outcome:'后续结局',directory:'调查目录',forum:'校园论坛',post:'帖子阅读',files:'我的资料',doc:'资料阅读器',chat:'对话记录',chats:'对话记录',notes:'调查笔记',deduction:'整理判断',profile:'人物资料',search:'站内搜索',end:'第一幕尾声',chapter:'继续调查',accounts:'账号登录',locker:'人物资料柜',folder:'班级资料夹',casefile:'资料阅读器',compare:'报告对照',resolution:'案件结局'};$('#windowTitle').textContent='青禾论坛 — '+(names[section]||'校园记录');$('#taskTitle').textContent=names[section]||'青禾论坛';$('#virtualAddress').value='qinghe.local/'+(['annex','archive','recover','staff-login','mailbox','vault','board','outcome'].includes(section)?({annex:'my/notebook?chapter=',archive:'archive/view?id=',recover:'member.php?action=recover&ref=', 'staff-login':'member.php?action=staff_login&ref=',mailbox:'mail/drafts?ref=',vault:'archive/decrypt?ref=',board:'my/evidence?ref=',outcome:'my/case-summary?ending='}[section]+encodeURIComponent(location.hash.split('/')[1]||'')):section==='directory'?'my/notebook?index=1':section==='accounts'?'member.php?action=login':section==='locker'?'home.php?user='+state.activeAccount:section==='chapter'?'my/notebook?chapter='+encodeURIComponent(location.hash.split('/')[1]||'4'):section==='casefile'||section==='folder'?'my/files':section==='compare'?'my/compare':section==='resolution'?'my/case-summary':section==='forum'?'forum.php':section==='post'?'thread.php?id='+encodeURIComponent(location.hash.split('/')[1]||''):section==='search'?'search.php':section==='chat'||section==='chats'?'messages.php':section==='files'||section==='doc'?'my/files':section==='notes'||section==='deduction'?'my/notebook':'member.php');$('#windowBack').disabled=routeTrail.length<2;}
function render(){autoRead.cancel();network.suspend();const route=location.hash||'#forum';if(immersion.navigate(route,renderNow,enteredComputer))return;renderNow();}
function renderNow(){if(reader.open)reader.close();const hash=location.hash||'#forum';let decoded;try{decoded=decodeURIComponent(hash);}catch{decoded='#forum';}const [section,id='']=decoded.slice(1).split('/');const redirect=legacyNetworkRoute(section,id);if(redirect){location.hash=redirect;return;}const isDoc=section==='doc'||section==='casefile';if(!isDoc){lastBase=hash;if(routeTrail.at(-1)!==hash)routeTrail.push(hash);}syncWindow(section);siteShell.sync(hash);let nav='forum',crumb='校园论坛';if(section==='files'||isDoc){nav='files';crumb='我的资料';}else if(section==='chats'||section==='chat'){nav='chats';crumb='对话记录';}else if(['notes','deduction','end','chapter','compare','resolution'].includes(section)){nav='notes';crumb='调查笔记';}if(['accounts','locker','folder','casefile'].includes(section)){nav='files';crumb='资料与账号';}if(['annex','board','outcome','directory'].includes(section)){nav='notes';crumb=section==='directory'?'调查目录':'后续调查';}if(['archive','recover','staff-login','mailbox','vault'].includes(section)){nav='files';crumb='授权资料副本';}document.querySelectorAll('[data-nav]').forEach(e=>e.classList.toggle('active',e.dataset.nav===nav));$('#breadcrumb').textContent=crumb;switch(section){case 'directory':break;case 'forum':renderForum();break;case 'post':renderPost(id);break;case 'files':renderFiles();break;case 'doc':renderFiles();if(enteredComputer)openDoc(id);break;case 'casefile':renderFiles();if(enteredComputer)openCaseDoc(id);break;case 'chapter':renderChapter(Number(id)||4);break;case 'accounts':renderAccounts(id);break;case 'locker':renderLocker(id);break;case 'folder':renderFolder(id);break;case 'compare':renderComparison();break;case 'resolution':renderResolution();break;case 'chats':case 'chat':renderChat(id||'azhe');break;case 'notes':renderNotes();break;case 'deduction':renderDeduction();break;case 'profile':renderProfile(id);break;case 'search':renderSearch(decoded.slice('#search/'.length));break;case 'end':renderEnding();break;default:if(!network.handleRoute(section,id)&&!archive.handleRoute(section,id))missing();}archive.decorate(section);immersion.decorate(section,id);scheduleOriginalRead(section,id);updateChrome();if(!['portal','video','dynamic','pan'].includes(section))document.title=(section==='post'?getVisiblePosts().find(p=>p.id===id)?.title||'档案':crumb)+' — 第三份阳性报告';if(!isDoc){const shell=$('.main-shell');if(shell)shell.scrollTop=0;if(enteredComputer)view.focus({preventScroll:true});}}
function showReader(title,body){$('#readerTitle').textContent=title;$('#readerBody').innerHTML=body;if(!reader.open)reader.showModal();}
function closeReader(){reader.close();autoRead.refresh();if(location.hash.startsWith('#doc/')||location.hash.startsWith('#casefile/'))location.hash=lastBase;}
function openDoc(id){if(!canReadDoc(state,id)){showReader('资料暂不可用','<div class="reader-content"><p>这份资料还没有出现在你的记录里。</p><a href="#notes" class="secondary">回到笔记</a></div>');return;}const d=docs[id];if(!d){showReader('资料未找到','<div class="reader-content"><p>这份资料不存在。请从“我的资料”重新打开。</p></div>');return;}if(d.kind!=='report')markRead('doc:'+id);if(id==='notebook'&&state.deduced&&state.read.includes('chat:yida'))markRead('memory:yida-letter');if(d.kind!=='report'&&!state.opened.includes(id)){state.opened.push(id);save();}zoom=100;let html='';if(d.kind==='report'){html=`<div class="viewer-tools"><button data-zoom="-20" aria-label="缩小报告">−</button><span id="zoomLabel">100%</span><button data-zoom="20" aria-label="放大报告">＋</button><button data-zoom-reset>适合窗口</button><button id="textToggle" aria-expanded="false">查看文字说明</button></div><div class="image-viewport"><img id="reportImage" src="${d.image}" alt="${d.title}：${d.text}"></div><div class="image-text" id="imageText" hidden>${d.text}</div><div class="reader-bottom"><small>${d.subtitle}<br></small>${clueButton(OPENING_DOC_CLUES[id],'立即记下')}<a class="collect-button" href="#post/reports">返回原帖 ↗</a></div>`;}else if(d.kind==='notebook'){if(!state.easter.includes('bathroom')){state.easter.push('bathroom');save();}html=`<div class="reader-content"><div class="reader-overline">益达的本子 · 借来的两页</div><div class="diary"><h3>3月6日，星期四</h3><small>中午回来补的</small><p>by早上上厕所没带纸，在里面喊我。我六点二十就去教室了，根本没听见。</p><p>他中午回来自己讲，说喊了好几遍没人理，最后没办法，拿花洒冲的。杰哥刚吃了一口饭，差点喷出来。</p><p>写这段的时候by还在旁边，说我写得跟他当时很从容一样。他说一点也不从容，让我把“没办法”三个字加上。</p><p class="diary-add">by：你最好是真的没听见。</p></div><div class="diary"><h3>3月11日，星期二</h3><p>早上拉肚子，第一节差点迟到。杰哥问我是不是昨天吃多了，我吃的还没他一半多。</p><p>晚上没跟他们一起吃面，自己去食堂买了点别的。先这样，别再折腾肚子了。</p><p class="diary-add">后补：家里带去查过了，没查出幽门。报告放家里，没带回来。</p></div>${clueButton('diary','＋ 记下益达这次拉肚子的时间')}<p class="small-text">益达只借了这两页，别的还夹在他本子里。</p>${canReadDoc(state,'letter')?`<div class="private-memory"><h3>收起本子的时候</h3><p>回到宿舍，你把本子还给益达。一只旧信封从后面的书页里滑出来，他刚捡起来，杰哥就从上铺探了个头。</p><p>“哟，还留着呢？”</p><p>益达把信封往本子里一夹：“你小点声，门还开着。”</p><p>你想起来了，是运动会之后那封。平时只有你们宿舍拿它开过玩笑，外面没人知道。杰哥看益达没真生气，又压低声音问你还记不记得那句。</p><a href="#doc/letter" class="secondary">回想那封信</a></div>`:''}</div>`;}else if(d.kind==='paper'){html=`<div class="reader-content"><div class="reader-overline">3月14日 · 语文周测</div><div class="diary"><h3>高三语文周测 · 你的试卷</h3><p>阅读理解：最后两道未完成。</p><p>作文：只写了开头，下面的格子空着。</p><p class="diary-add">“需要去校医室吗？”<br>你当时摇了头。</p></div><p>那天你多次离开教室。益达已经在写作文。陈叙的座位空着，桌上连水杯也没放。</p><p>你只记得当时有点羡慕：有个人整场都不用写。</p><a class="secondary" href="#post/exam">看看同学怎么聊这场周测 ↗</a></div>`;}else if(d.kind==='score'){if(!state.easter.includes('score')){state.easter.push('score');save();}html=`<div class="reader-content"><div class="reader-overline">杰哥的手机 · 语文资料</div><div class="score-sheet"><small>PHIGROS / BEST SCORE</small><h3>0948721</h3><p>Accuracy 94.87%　|　Rank A</p><div class="score-line"></div><p>文件夹名称：语文资料<br>同名文件：语文资料_最终版.png</p></div><p>“就这张。”杰哥把手机递过来，“别问前面打了多少次。”</p><p>你说没问。他补了一句：“也别跟老师说。”</p><div class="source-disclaimer">已发现彩蛋：杰哥的“语文资料”。</div></div>`;}else if(d.kind==='letter'){if(!state.easter.includes('letter')){state.easter.push('letter');save();}html=`<div class="reader-content"><div class="reader-overline">原信由益达保存</div><h2>“圣经”</h2><p>运动会之后，益达把那封信收了起来。室友总拿其中一句开玩笑，原信却一直没有离开他自己的旧物袋。</p><div class="letter"><small>你记得的片段</small><p>我以前不喜欢你，<br>以后也不会喜欢你。</p></div><p>“这句你们不是都会背了。”益达把信拿回去，“差不多得了，别拍。”</p><p>杰哥还想再念一遍，被益达用枕头砸了回去。你把信封递给他，看他原样收好。</p><div class="source-disclaimer">已发现彩蛋：“圣经”。信一直在益达这里。</div></div>`;}showReader(d.title,html);}
function showIntro(){introStep=0;renderIntro();if(!story.open)story.showModal();}
function renderIntro(){const s=intro[introStep];$('#storyBody').innerHTML=`<div class="story-body"><div class="story-meta"><span>第三份阳性报告</span><span>一个高三宿舍的故事</span></div><h1 id="storyTitle">${s.title}</h1><div class="reader-overline">${s.kicker}</div><div class="story-text">${s.body}</div><div class="story-context">你扮演 by。点“接着读”翻页，也可以先进入论坛。</div><div class="story-actions"><button data-intro-skip>${introStep===0?'直接进入论坛':'收起，进入论坛'}</button><span class="story-pagination">0${introStep+1} / 04</span><button class="primary" data-intro-next>${introStep===intro.length-1?'打开那篇帖子':'接着读'} <span>→</span></button></div>${introStep>0?'<button class="small-text" data-intro-prev style="margin-top:15px;padding:0">← 上一页</button>':''}</div>`;}
function finishIntro(openPost=false){state.introDone=true;save();story.close();if(openPost)location.hash='#post/reports';}
function showHelp(){showReader('调查指南',`<div class="reader-content"><div class="reader-overline">操作说明</div><h2>怎么玩</h2><div class="guide-step"><strong>01 / 从一个词开始</strong><p>在论坛搜索人物、事件或一句记得的话。人物主页和附件引用也能带你找到资料。</p></div><div class="guide-step"><strong>02 / 留下依据</strong><p>原案里的附件、原帖和关键对话，打开阅读1.5秒后会自动收进调查笔记，也可以点按钮立即保存。</p></div><div class="guide-step"><strong>03 / 多问几个人</strong><p>帖子、回忆、附言不一定在说同一件事。看看是谁说的、当时知道什么。</p></div><div class="guide-step"><strong>04 / 推理可以修改</strong><p>记下几条线索以后，到“调查笔记”里选“整理一次判断”。选错可以再试，不会扣分。</p></div><p>没有真实倒计时。进度只保存在当前浏览器；清除浏览器数据会清除存档。搜索与所有内容都在这部虚构作品内。</p><div class="ending-actions"><button class="secondary" data-help-intro>重读开场 ↗</button><a class="primary" href="#deduction">去整理判断 →</a></div></div>`);}
let baseHintContext=null;
function showBaseHint(advance=false){let hints;if(!state.clues.includes('post'))hints=['先从那篇有三份附件的帖子开始。','看看第三张图是怎么来的，阿哲在正文后面补了一句。','打开“最近有三位同学查出幽门”帖子，点击底部“把这篇帖子记下来”。'];else if(!state.clues.includes('source'))hints=['知道帖子是谁整理的，就去问问他。','阿哲可以解释投稿的来源。他知道第三位是谁吗？','打开“对话记录 → 阿哲”，读完后点击“记下投稿来源的说明”。'];else if(!state.deduced)hints=['先回答一个小问题：现在真的能认出第三位了吗？','阿哲认识第三个人吗？楼下说的“同一宿舍”，有人确认过吗？','去“调查笔记 → 整理一次判断”。选择“原帖里的三份材料”和“阿哲的投稿来源说明”，再判断身份是否已核实。'];else if(!state.finished)hints=['你已经有了第一条判断。接着看看故事会往哪里走。','调查笔记上方有继续故事的入口。','打开调查笔记，选择“继续故事：益达的那两页记录”。'];else hints=['还可以继续调查夜宵。','打开调查笔记，进入下一章。','选择“食堂关门以后”继续。'];const context=hints[0];if(baseHintContext!==context){baseHintContext=context;state.hint=0;}if(advance===true)state.hint=Math.min(2,state.hint+1);save();showReader('游戏提示',hintMarkup('下一步可以查什么',hints,state.hint,'原案调查'));}

function requestReset(){showReader('重新开始前',`<div class="reader-content"><h2>清除这份本地进度？</h2><p>已读内容、调查笔记、推理结果和彩蛋记录都会重置。其他网站的数据不受影响。</p><div class="ending-actions"><button class="danger-button" data-reset-confirm>确认清除并从开场开始</button><button class="secondary" data-reset-cancel>保留进度</button></div></div>`);}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(el.tagName==='A'&&el.getAttribute('href')?.startsWith('#')&&!$('#cover').hidden)enterComputer(false);if(el.matches('[data-open-app]')){openApp('#'+el.dataset.openApp);return;}if(el.matches('[data-collect]')){collect(el.dataset.collect);return;}if(el.matches('[data-doc]')){location.hash='#doc/'+el.dataset.doc;return;}if(el.matches('[data-query]')){location.hash='#search/'+encodeURIComponent(el.dataset.query);return;}if(el.matches('[data-filter]')){currentFilter=el.dataset.filter;renderForum();return;}if(el.matches('[data-intro-next]')){if(introStep<intro.length-1){introStep++;renderIntro();}else finishIntro(true);return;}if(el.matches('[data-intro-prev]')){introStep=Math.max(0,introStep-1);renderIntro();return;}if(el.matches('[data-intro-skip]')){finishIntro();return;}if(el.matches('[data-help-intro]')){reader.close();showIntro();return;}if(el.matches('[data-next-hint]')){showHint(true);return;}if(el.matches('[data-reset-request]')){requestReset();return;}if(el.matches('[data-reset-cancel]')){showAbout();return;}if(el.matches('[data-reset-confirm]')){autoRead.cancel();state=freshState();archive.reset();immersion.reset();network.reset();save();reader.close();location.hash='#forum';render();enterComputer(true);return;}if(el.matches('[data-zoom]')){zoom=Math.max(60,Math.min(240,zoom+Number(el.dataset.zoom)));$('#reportImage').style.width=zoom+'%';$('#zoomLabel').textContent=zoom+'%';return;}if(el.matches('[data-zoom-reset]')){zoom=100;$('#reportImage').style.width='100%';$('#zoomLabel').textContent='100%';return;}if(el.id==='textToggle'){const panel=$('#imageText');panel.hidden=!panel.hidden;el.setAttribute('aria-expanded',String(!panel.hidden));el.textContent=panel.hidden?'查看文字说明':'收起文字说明';return;}});
document.addEventListener('submit',e=>{if(e.target.matches('[data-search]')){e.preventDefault();const q=new FormData(e.target).get('q').trim().slice(0,120);if(q)location.hash='#search/'+encodeURIComponent(q);else toast('先输入一个关键词。');return;}if(e.target.id==='deductionForm'){e.preventDefault();const data=new FormData(e.target);const result=judgeDeduction(data.getAll('evidence'),data.get('conclusion'));const out=$('#deductionFeedback');out.textContent=result.message;out.classList.toggle('success',result.ok);if(result.ok){state.deduced=true;save();if(!$('#continueStory')){const a=document.createElement('a');a.className='primary';a.id='continueStory';a.href='#end';a.textContent='继续故事 →';e.target.querySelector('.deduction-bottom').append(a);}toast('记好了，接着看吧。');}}});
$('#closeReader').addEventListener('click',closeReader);reader.addEventListener('cancel',e=>{e.preventDefault();closeReader();});reader.addEventListener('click',e=>{if(e.target===reader){const r=reader.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeReader();}});story.addEventListener('cancel',e=>{e.preventDefault();finishIntro();});$('#replayIntro').addEventListener('click',showIntro);$('#helpButton').addEventListener('click',showHelp);$('#hintButton').addEventListener('click',showHint);$('#aboutButton').addEventListener('click',showAbout);window.addEventListener('hashchange',render);
$('#coverStart').addEventListener('click',()=>enterComputer(true));$('#coverContinue').addEventListener('click',()=>enterComputer(false));$('#coverGuide').addEventListener('click',showHelp);$('#coverAbout').addEventListener('click',showAbout);$('#desktopMenu').addEventListener('click',showCover);$('#taskStart').addEventListener('click',showCover);$('#windowMinimize').addEventListener('click',minimizeApp);$('#windowClose').addEventListener('click',minimizeApp);$('#taskApp').addEventListener('click',()=>openApp());$('#windowHome').addEventListener('click',()=>openApp(siteShell.home()));$('#windowRefresh').addEventListener('click',()=>{render();toast('页面已刷新。');});$('#windowMaximize').addEventListener('click',()=>{windowMaximized=!windowMaximized;$('#appWindow').classList.toggle('maximized',windowMaximized);$('#windowMaximize').setAttribute('aria-pressed',String(windowMaximized));$('#windowMaximize').setAttribute('aria-label',windowMaximized?'还原窗口':'最大化窗口');$('#windowMaximize').title=windowMaximized?'还原':'最大化';});$('#windowBack').addEventListener('click',()=>{if(routeTrail.length>1){routeTrail.pop();const previous=routeTrail.pop();location.hash=previous;}});

function getVisiblePosts(){const all=[...posts,...casePosts.filter(p=>p.stage<0||(state.finished&&state.caseStage>=p.stage))];return all.map(p=>p.id==='reports'&&state.caseStage>=4?{...p,title:p.title+'【材料待核实】',body:'<div class="source-disclaimer">03-26 编辑补充：A/C图片同源，第三张暂不作为独立病例统计。下面保留原帖经过，最终更正会另附。</div>'+p.body}:p);}
function canAccessCaseDoc(d){return !!d&&state.finished&&state.caseStage>=d.stage&&(!d.folder||state.folders.includes(d.folder))&&(d.owner==='by'||state.activeAccount===d.owner||state.savedDocs.includes(d.id));}
function getSearchIndex(){return [...archive.searchEntries(),...searchIndex.map(x=>({...x,keywords:[...(x.keywords||[]),...(HISTORY_TOPICS[x.id]||[]),...({noodles:['夜宵账单'],exam:['周测作文'],printing:['打印委托'],sports:['旧照片']}[x.id]||[])]})).filter(x=>!x.route.startsWith('#doc/')||canReadDoc(state,x.route.slice(5))),...casePosts.filter(p=>getVisiblePosts().some(x=>x.id===p.id)).map(p=>({title:p.title,type:'帖子',route:'#post/'+p.id,summary:p.summary,keywords:[p.body.replace(/<[^>]+>/g,''),p.author,p.tag]})),...Object.values(caseDocs).filter(canAccessCaseDoc).map(d=>({title:d.title,type:d.owner==='by'?'我的记录':'已取得的资料',route:'#casefile/'+d.id,summary:d.summary,keywords:d.keywords})),...(state.finished?[{title:'继续调查 · '+campaignChapters[Math.min(state.caseStage,8)].title,type:'调查记录',route:'#chapter/'+(Math.min(state.caseStage,8)+4),summary:'继续上次查到的地方。',keywords:['继续','主线','章节','下一步']}]:[])];}
function caseResume(){if(!state.finished)return '';const c=campaignChapters[Math.min(state.caseStage,8)];return `<section class="case-resume"><div><small>${state.caseSolved?'案件已查清':'接着上次的调查'}</small><strong>第${c.number}章　${c.title}</strong></div><a class="primary" href="${state.caseSolved?'#resolution':'#chapter/'+c.number}">${state.caseSolved?'查看结局':'继续调查'} →</a></section>`;}
function renderForum(){renderBaseForum();view.insertAdjacentHTML('afterbegin',caseResume());const p=people[state.activeAccount]||people.by;const node=view.querySelector('.forum-account');if(node)node.innerHTML=`<a href="#accounts">${avatar(state.activeAccount)}</a><span><a href="#accounts"><strong>${p.name}</strong></a><small><a href="#accounts">切换账号</a>　<a href="#files">我的资料</a></small></span>`;}
function renderFiles(){renderBaseFiles();if(!state.finished)return;const available=Object.values(caseDocs).filter(canAccessCaseDoc);view.insertAdjacentHTML('afterbegin',caseResume());view.insertAdjacentHTML('beforeend',`<div class="file-section-title"><h2>后续调查资料</h2><a href="#accounts">账号与资料柜 →</a></div><div class="page-grid">${available.map(d=>`<a class="file-card" href="#casefile/${d.id}"><span class="file-icon">${d.image?'图':'文'}</span><h2>${d.title}</h2><p>${d.summary}</p><small>${state.savedDocs.includes(d.id)?'已保存副本':d.owner==='by'?'我的记录':people[d.owner].name+'的资料柜'} →</small></a>`).join('')}</div>`);}
function renderNotes(){renderBaseNotes();if(!state.finished)return;view.querySelector('.completed-card')?.remove();const next=view.querySelector('.notebook-actions a.primary');if(next){next.href='#chapter/'+(Math.min(state.caseStage,8)+4);next.textContent=state.caseSolved?'回看最后一章':'继续当前调查 →';}view.insertAdjacentHTML('afterbegin',caseResume()+`<details class="chapter-directory"><summary>已走过的章节 / 当前调查</summary><a href="#end">第1—3章　周测和第三份报告</a>${campaignChapters.filter(c=>c.number<=state.caseStage+4).map(c=>`<a href="#chapter/${c.number}">第${c.number}章　${c.title}${c.number<state.caseStage+4?'　✓':''}</a>`).join('')}</details>`);}
function campaignLocked(){view.innerHTML=heading('','这段记录还没有出现','先把手边的线索看完，再继续往后。')+`<a class="primary" href="${state.finished?'#chapter/'+(Math.min(state.caseStage,8)+4):'#deduction'}">回到当前调查</a>`;}
function renderChapter(number){if(!state.finished||!Number.isInteger(number)||number<4||number>12||number>state.caseStage+4){campaignLocked();return;}const step=number-4,c=campaignChapters[step];markRead('chapter:'+number);view.innerHTML=`<div class="chapter-breadcrumb"><a href="#notes">调查笔记</a><span>第 ${number} / 19 章</span></div><section class="chapter-heading"><small>${c.date}</small><h1>${c.title}</h1></section><article class="chapter-story">${c.story}</article><nav class="chapter-links" aria-label="本章资料">${c.links.map(([t,r])=>`<a class="secondary" href="${r}">${t} →</a>`).join('')}</nav>${step===8?renderEndingChoice():`<section class="case-workbench"><header><small>手边的事</small><h2>${c.objective}</h2></header>${step<state.caseStage?`<div class="step-done">✓ 这一段已经核对。<a href="#chapter/${number+1}">继续下一章 →</a></div>`:''}${renderCasePuzzle(step)}<div class="case-feedback" id="caseFeedback" role="status"></div><div id="chapterAfter" ${step<state.caseStage?'':'hidden'}><article class="chapter-after">${c.after||''}</article><a class="primary" href="#chapter/${number+1}">接着看：${campaignChapters[step+1].title} →</a></div></section>`}`;}
function caseOrderMarkup(){const names={pickup:'杰哥在学校食堂取餐，把夜宵带回宿舍',shower:'杰哥先去洗澡，面放在桌上',mix:'by听见杰哥喊话，把底下的酱拌匀',taste:'乌鸡来串门，和by一起尝了几口面'};return caseOrder.map((id,i)=>`<li data-event="${id}"><span class="order-number">${i+1}</span><p>${names[id]}</p><button type="button" data-case-move="${i}" data-direction="-1" ${i===0?'disabled':''} aria-label="把这件事往前移">↑</button><button type="button" data-case-move="${i}" data-direction="1" ${i===3?'disabled':''} aria-label="把这件事往后移">↓</button></li>`).join('');}
function selectField(name,label,options){return `<label class="case-field"><span>${label}</span><select name="${name}" required><option value="">请选择</option>${options.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label>`;}
function renderCasePuzzle(step){let inner='';if(step===0)inner=`<p>用上下箭头调整先后。小票和照片可以来回打开，不限次数。</p><ol class="case-order" id="caseOrder">${caseOrderMarkup()}</ol>${selectField('bowl','益达面前的那只碗，对应哪一份？',[['shared','同一碗火鸡面分出来的'],['own','他另买的紫菜汤，旁边是饭团'],['unknown','照片里没有碗']])}`;
if(step===1)inner=`<div class="deleted-file-list"><span>IMG_1018_21</span><span>IMG_1018_22</span><span>IMG_1018_23</span></div>${selectField('deleted','私信里说删掉的三张图是什么？',[['report','检查报告'],['letter','未经同意拍下的信件照片'],['meal','夜宵订单']])}${selectField('result','益达主动带来的那份结果写着什么？',[['positive','阳性'],['negative','阴性'],['none','他没有去检查']])}<p class="small-text">这段信件私事只在宿舍里说，不会自动发到论坛。</p>`;
if(step===2){const opts=[['dorm','你们宿舍几个人早已知道'],['chen','在这次午休，只向陈叙提过'],['public','原帖已经公开写过']];inner='<p>给三句话标出在匿名回复出现前的知情范围。</p>'+selectField('bathroom','早上没带纸，最后用了花洒',opts)+selectField('letter','删的是那封旧信的照片',opts)+selectField('folder','复印的两页夹在语文卷最后面',opts);}
if(step===3)return comparisonMarkup(true);
if(step===4)inner=`<p>选择现有记录支持的流转方向。只画已经确认发生过的，不补猜测。</p><div class="flow-options">${[['by-jie','你 → 杰哥：留存原图副本'],['by-chen','你 → 陈叙：原图用于打印'],['anonymous-azhe','匿名账号 → 阿哲：第三张投稿'],['yida-azhe','益达 → 阿哲：第三张匿名投稿'],['jie-chen','杰哥 → 陈叙：改图后代发']].map(([v,t])=>`<label><input type="checkbox" name="paths" value="${v}"><span>${t}</span></label>`).join('')}</div>`;
if(step===5)inner=`<p>输入月日即可，例如0314或03-14。也可以填写完整年月日。</p>${[['absence','陈叙缺席的那次周测'],['check','你的阳性结果'],['print','你请陈叙打印原图']].map(([name,text])=>`<label class="case-field"><span>${text}</span><input name="${name}" type="text" inputmode="numeric" maxlength="12" autocomplete="off" placeholder="月日" required></label>`).join('')}`;
if(step===6)inner=selectField('edit','谁将原帖正文改为“材料待核实”？',[['azhe','楼主阿哲'],['author','匿名回复作者'],['teacher','老师代改']])+selectField('remove','谁撤回了6、7楼？',[['azhe','阿哲'],['author','匿名回复作者自己'],['automatic','系统自动删除']]);
if(step===7){const clueOpts=state.clues.map(id=>[id,CLUES[id].code+' · '+CLUES[id].title]);inner=selectField('person','这些材料需要追问谁？',[['yida','益达'],['jie','杰哥'],['chen','陈叙'],['azhe','阿哲']])+`<div class="final-evidence-grid">${selectField('image','第一层：C图为什么不独立？',clueOpts)}${selectField('access','第二层：他如何接触原图？',clueOpts)}${selectField('information','第三层：匿名回复如何跟私下信息对应？',clueOpts)}${selectField('motive','第四层：哪个旧事件让他需要维持说法？',clueOpts)}</div>`+selectField('source','这能否确定你和乌鸡的感染来源？',[['meal','已经证明来自学校食堂夜宵'],['yida','已经证明由益达传来'],['unknown','仍不能确定，要与造假事件分开']]);}
return `<form class="case-puzzle" data-case-step="${step}">${inner}<button class="primary" type="submit">${step===7?'把说明整理好':'记下这一步'} →</button><p class="small-text">原案资料打开阅读片刻后会自动收进调查本，也可立即点保存。</p></form>`;}
function comparisonMarkup(withForm){return `<div class="comparison-tools"><button type="button" class="secondary active" data-compare-mode="side">并排看</button><button type="button" class="secondary" data-compare-mode="overlay">叠在一起</button><label>叠图透明度 <input type="range" min="0" max="100" value="50" data-compare-opacity aria-label="第三张报告的叠图透明度"></label></div><div class="comparison-grid" id="compareSide">${[['A','assets/report-by-v3.svg'],['C','assets/report-unknown-v3.svg']].map(([label,src])=>`<figure><figcaption>${label==='A'?'A · 你的原报告':'C · 匿名投稿'}<small>${label==='A'?'2025-03-15':'2025-03-14'}</small></figcaption><div class="comparison-image"><img src="${src}" alt="${label}报告原图，可放大核对纸面和印刷痕迹"><button type="button" class="evidence-pin pin-fold" data-mark="fold" aria-label="标记纸张折痕" aria-pressed="false">1</button><button type="button" class="evidence-pin pin-circle" data-mark="circle" aria-label="标记手写圈画" aria-pressed="false">2</button><button type="button" class="evidence-pin pin-stamp" data-mark="stamp" aria-label="标记印章角度" aria-pressed="false">3</button><button type="button" class="evidence-pin pin-noise" data-mark="noise" aria-label="标记打印灰点" aria-pressed="false">4</button></div></figure>`).join('')}</div><div class="comparison-overlay" id="compareOverlay" hidden><img src="assets/report-by-v3.svg" alt="报告A底图"><img class="overlaid-report" id="overlaidReport" src="assets/report-unknown-v3.svg" alt="报告C叠图" style="opacity:.5"></div><details class="comparison-reference"><summary>调出报告B作为参照</summary><img src="assets/report-wuji-v3.svg" alt="报告B原图，用于核对哪些印刷痕迹可能重复"></details><p class="small-text">图片从原帖开始就保留这些痕迹。点击图上编号或勾选下面的文字，两种方式都可以。</p>${withForm?`<form class="case-puzzle" data-case-step="3"><div class="comparison-marks">${[['stamp','3 · 红色印章的盖印角度相近'],['fold','1 · 左下折痕的走向与转弯'],['template','检测项目与版式相同'],['noise','4 · 背景灰点与打印噪点相似'],['positive','两张都写着阳性'],['circle','2 · 蓝笔圈画右侧的缺口']].map(([value,text])=>`<label><input type="checkbox" name="marks" value="${value}"><span>${text}</span></label>`).join('')}</div><p><a href="#casefile/submission">还要核对阿哲收到的原始投稿 →</a></p><button class="primary" type="submit">提交比对依据 →</button></form>`:''}`;}
function renderComparison(){if(!state.finished||state.caseStage<3)return campaignLocked();view.innerHTML=heading('','报告对照','A与C来自最早那篇帖子。比对纸张留下的独特细节。')+`<section class="case-workbench">${comparisonMarkup(true)}<div class="case-feedback" id="caseFeedback" role="status"></div><div id="chapterAfter" hidden><p>原图和原始投稿已经对上。</p><a class="primary" href="#chapter/8">继续：原图不只在手机里 →</a></div></section><a class="back-link" href="#chapter/7">回到本章</a>`;}
function renderAccounts(target=''){if(!state.finished)return campaignLocked();const eligible=Object.entries(GAME_ACCOUNTS).filter(([id])=>canUseAccount(state,id));const selected=eligible.find(([id])=>id===target);view.innerHTML=heading('','青禾校园网 · 账号登录','用人物给你的线索登录资料柜。已保存的副本，回到by账号也能查阅。')+`<section class="account-current">当前账号：<strong>${people[state.activeAccount]?.name||'by'}</strong>${state.activeAccount!=='by'?'<button class="secondary" data-account-home>切回by</button>':''}</section><div class="account-layout"><form class="account-form" id="gameLogin" autocomplete="off"><span class="account-logo">禾</span><h2>${selected?selected[1].name+'的账号':'登录其他账号'}</h2><label>账号<input type="text" name="gameUser" value="${selected?selected[1].username:''}" autocomplete="off" autocapitalize="off" spellcheck="false" required></label><label>口令<input type="password" name="gamePass" autocomplete="off" required></label><p id="loginFeedback" class="case-feedback" role="status"></p><button class="primary" type="submit">登录</button></form><aside class="account-clues"><h2>目前拿到的账号线索</h2>${eligible.map(([id,a])=>`<article>${avatar(id)}<div><strong>${a.name}</strong><p>${id==='jie'?'账号jiege；规则在存根背面，所需的另一份记录在旧账帖。':id==='yida'?'账号yida；照片袋留有规则，旧帖保留了拍摄登记。':'阅览号heshe；收稿页和旧打印登记需互相核对。'}</p><a href="#casefile/${id==='jie'?'pickup':id==='yida'?'sports-slip':'editor-note'}">回看口令线索</a>　<a href="#locker/${id}">资料柜</a></div></article>`).join('')}<p class="small-text">先读人物给你的账号说明。尚未出现的账号不会列在这里。</p></aside></div>`;}
function renderLocker(id){if(!canUseAccount(state,id))return campaignLocked();if(state.activeAccount!==id){view.innerHTML=heading('',people[id].name+'的资料柜','需要切换到这个账号。')+`<a class="primary" href="#accounts/${id}">去登录</a>`;return;}const list=Object.values(caseDocs).filter(d=>d.owner===id&&canAccessCaseDoc(d));view.innerHTML=heading('',people[id].name+'的资料柜','本次提供的相关文件与私信副本。')+`<div class="locker-toolbar"><span>已登录：${GAME_ACCOUNTS[id].username}</span><a class="secondary" href="#accounts">切换账号</a><a class="primary" href="#chapter/${Math.min(state.caseStage,8)+4}">回到当前调查 →</a></div><div class="locker-list">${list.map(d=>`<a href="#casefile/${d.id}"><span class="file-icon">${d.image?'图':'文'}</span><div><strong>${d.title}</strong><p>${d.summary}</p></div><span>${state.savedDocs.includes(d.id)?'已保存':'打开 →'}</span></a>`).join('')}</div>`;}
function openCaseDoc(id){const d=caseDocs[id];if(!d||!canAccessCaseDoc(d)){const login=d&&state.finished&&state.caseStage>=d.stage&&!state.savedDocs.includes(id)&&d.owner!=='by'&&canUseAccount(state,d.owner);showReader('资料暂不可用',`<div class="reader-content"><p>${login?'需要切换到提供这份资料的账号。':'这份资料还没有出现在你的记录里。'}</p>${login?`<a class="primary" href="#accounts/${d.owner}">去登录</a>`:d?.folder&&state.caseStage>=5?'<a class="secondary" href="#folder/makeup">打开班级资料夹</a>':'<a class="secondary" href="#notes">回到调查笔记</a>'}</div>`);return;}if(!d.image)markRead('casefile:'+id);if(d.easter&&!state.easter.includes(d.easter)){state.easter.push(d.easter);save();}zoom=100;showReader(d.title,`${d.image?`<div class="viewer-tools"><button data-zoom="-20" aria-label="缩小图片">−</button><span id="zoomLabel">100%</span><button data-zoom="20" aria-label="放大图片">＋</button><button data-zoom-reset>适合窗口</button></div><div class="image-viewport"><img id="reportImage" src="${d.image}" alt="${d.summary}"></div>`:''}<div class="reader-content case-document"><div class="reader-overline">${state.savedDocs.includes(id)?'我保存的副本':d.owner==='by'?'自己的记录':people[d.owner].name+'提供的资料'}</div>${d.body}${d.clue?`<div class="case-save-row"><button class="collect-button ${state.savedDocs.includes(id)?'collected':''}" data-case-save="${id}">${state.savedDocs.includes(id)?'✓ 已保存副本和线索':'＋ 保存到我的资料和笔记'}</button><a href="#chapter/${Math.min(state.caseStage,8)+4}">回到当前调查 →</a></div>`:''}${d.easter?'<p class="small-text">已发现一个宿舍彩蛋。</p>':''}</div>`);}
function saveCaseDoc(id,automatic=false){const d=caseDocs[id];if(!d||!canAccessCaseDoc(d)||!d.clue)return false;let changed=addClue(state,d.clue);if(!state.savedDocs.includes(id)){state.savedDocs.push(id);changed=true;}if(!state.read.includes('casefile:'+id)){state.read.push('casefile:'+id);changed=true;}if(changed)save();document.querySelectorAll(`[data-case-save="${id}"]`).forEach(b=>{b.textContent='✓ 已保存副本和线索';b.classList.add('collected');});if(changed)toast((automatic?'已自动收入调查本：':'已保存：')+d.title);return changed;}
function renderFolder(id){if(id!=='makeup'||!state.finished||state.caseStage<5)return campaignLocked();if(state.folders.includes('makeup')){view.innerHTML=heading('','班级资料夹','资料夹已经打开，口令不用重复输入。')+'<div class="locker-list"><a href="#casefile/makeup"><span class="file-icon">卷</span><div><strong>高三语文_03月28日_补测安排.pdf</strong><p>查看缺考补测安排</p></div><span>打开 →</span></a></div>';return;}view.innerHTML=heading('','班级资料夹','高三语文 · 补测安排压缩包')+`<form id="folderForm" class="folder-form"><span class="folder-large" aria-hidden="true">▰</span><h2>输入资料夹口令</h2><p>月日接24小时制开考时间，不加标点。通知在论坛里。</p><label>口令<input name="folderPass" placeholder="月日+时间(如03281430)" type="text" inputmode="numeric" maxlength="12" autocomplete="off" required></label><div class="case-feedback" id="folderFeedback" role="status"></div><button class="primary" type="submit">打开</button><a href="#post/makeup-time">看补测通知 →</a></form>`;}
function renderEndingChoice(){return `<section class="ending-choice"><h2>回到宿舍以后</h2><p>案件的真相不会因这个选择改变。你想怎么接着做？</p><button class="primary" data-ending-choice="apology">把之前误会的几件事，向益达说清楚</button><button class="secondary" data-ending-choice="later">先把材料交齐，道歉的话再找时间说</button>${state.endingChoice?'<a href="#resolution">重读已选结局 →</a>':''}</section>`;}
function renderResolution(){if(!state.caseSolved)return campaignLocked();if(!state.endingChoice){renderChapter(12);return;}view.innerHTML=heading('','下一次周测',state.endingChoice==='apology'?'原案尾声 · 话说清楚以后':'原案尾声 · 还可以说的话')+`<article class="chapter-story resolution-story">${caseEndings[state.endingChoice]}</article><section class="case-summary"><h2>第三份报告，还原完毕</h2><dl><div><dt>两份真实结果</dt><dd>by、乌鸡各自的检查结果真实存在。</dd></div><div><dt>第三张图</dt><dd>陈叙用by的报告照片改出，所标日期不能代表另一次独立检查。</dd></div><div><dt>匿名暗示</dt><dd>陈叙借由私下听到的信息，把调查引向益达，后来撤回了回复。</dd></div><div><dt>依然未知</dt><dd>现有校园记录没有确定两人实际感染的时间与来源。</dd></div></dl><p>已记线索 ${state.clues.length} 条　·　已发现彩蛋 ${state.easter.length} / 5</p><nav class="ending-actions"><a class="primary" href="#post/correction">阅读更正帖</a><a class="secondary" href="#notes">回看全部笔记</a><a class="secondary" href="#chapter/12">换个选择重读</a></nav></section>`;}
function showHint(advance=false){if(archive.hints(advance===true))return;if(!state.finished)return showBaseHint(advance);if(state.caseSolved){showReader('游戏提示','<div class="reader-content"><h2>案件已经查清</h2><p>可以回看资料柜与宿舍旧笔记。</p><a href="#chapter/12">回到第12章</a></div>');return;}const step=Math.min(state.caseStage,7);if(advance===true)state.caseHint=Math.min(2,state.caseHint+1);save();showReader('游戏提示',hintMarkup(campaignChapters[step].title,caseHints[step],state.caseHint,'第'+(step+4)+'章'));}
function showAbout(){showReader('关于游戏',`<div class="reader-content"><div class="reader-overline">内网界面版 · v2.3</div><h2>第三份阳性报告</h2><p>一部高三校园网页搜索解谜作品。十九章故事围绕三份检查材料和一份失实通报展开。可登录人物账号、找回授权阅览号、恢复草稿、解密附件，并在证据板连线质疑。</p><p>故事人物与资料均为虚构。现实中的诊疗请按医生安排，生活记录不用于判断谁传染了谁。医学内容参考<a href="https://medlineplus.gov/ency/article/007715.htm" target="_blank" rel="noopener noreferrer">MedlinePlus：幽门螺杆菌感染</a>。</p><p>账号与口令都是剧情的一部分，游戏内不需要查看代码。进度保存在当前浏览器，可随时退出后继续。</p><p>已发现彩蛋：${state.easter.length} / 5。</p><div class="reset-area"><p class="small-text">重新开始会清除本作品的本机进度。</p><button class="danger-button" data-reset-request>重新开始整个故事</button></div></div>`);}
function readCasePayload(form){const data=new FormData(form);return {order:[...caseOrder],bowl:data.get('bowl'),deleted:data.get('deleted'),result:data.get('result'),bathroom:data.get('bathroom'),letter:data.get('letter'),folder:data.get('folder'),marks:data.getAll('marks'),paths:data.getAll('paths'),absence:data.get('absence'),check:data.get('check'),print:data.get('print'),edit:data.get('edit'),remove:data.get('remove'),person:data.get('person'),image:data.get('image'),access:data.get('access'),information:data.get('information'),motive:data.get('motive'),source:data.get('source')};}
document.addEventListener('click',event=>{const button=event.target.closest('button,a');if(!button)return;if(button.matches('[data-case-save]')){saveCaseDoc(button.dataset.caseSave);return;}if(button.matches('[data-case-move]')){const from=Number(button.dataset.caseMove),to=from+Number(button.dataset.direction);if(to<0||to>=caseOrder.length)return;[caseOrder[from],caseOrder[to]]=[caseOrder[to],caseOrder[from]];$('#caseOrder').innerHTML=caseOrderMarkup();return;}if(button.matches('[data-account-home]')){state.activeAccount='by';save();renderAccounts();return;}if(button.matches('[data-ending-choice]')){if(chooseCaseEnding(state,button.dataset.endingChoice)){save();location.hash='#resolution';}return;}if(button.matches('[data-compare-mode]')){const overlay=button.dataset.compareMode==='overlay';$('#compareSide').hidden=overlay;$('#compareOverlay').hidden=!overlay;document.querySelectorAll('[data-compare-mode]').forEach(b=>b.classList.toggle('active',b===button));return;}if(button.matches('[data-mark]')){const key=button.dataset.mark,input=document.querySelector(`input[name="marks"][value="${key}"]`);if(input){input.checked=!input.checked;document.querySelectorAll(`[data-mark="${key}"]`).forEach(b=>{b.classList.toggle('marked',input.checked);b.setAttribute('aria-pressed',String(input.checked));});}}});
document.addEventListener('input',event=>{if(event.target.matches('[data-compare-opacity]'))$('#overlaidReport').style.opacity=String(Math.max(0,Math.min(100,Number(event.target.value)))/100);});
document.addEventListener('submit',event=>{const form=event.target;if(form.id==='gameLogin'){event.preventDefault();const data=new FormData(form),result=checkAccountLogin(state,data.get('gameUser'),data.get('gamePass'));$('#loginFeedback').textContent=result.message;if(result.ok){state.activeAccount=result.account;save();location.hash='#locker/'+result.account;}return;}if(form.id==='folderForm'){event.preventDefault();const result=unlockCaseFolder(state,new FormData(form).get('folderPass'));$('#folderFeedback').textContent=result.message;if(result.ok){save();renderFolder('makeup');}return;}if(form.matches('[data-case-step]')){event.preventDefault();const step=Number(form.dataset.caseStep),result=completeCaseStep(state,step,readCasePayload(form));const output=$('#caseFeedback');output.textContent=result.message;output.classList.toggle('success',result.ok);if(result.ok){save();document.dispatchEvent(new CustomEvent('qinghe:evidence-confirmed',{detail:{kind:'case',step}}));$('#chapterAfter').hidden=false;$('#chapterAfter').scrollIntoView?.({behavior:'smooth',block:'start'});toast(step===7?'说明整理好了，接着看老师核实后的经过。':'已记好，可以继续下一章。');}}});
$('#accountButton')?.addEventListener('click',()=>openApp('#accounts'));
render();syncCover();

document.addEventListener('input',e=>{if(!e.target.matches('[data-search] input[name=q]'))return;const guide=searchGuidance(e.target.value),list=e.target.form.querySelector('datalist');if(list)list.innerHTML=[...(guide.corrected?[guide.query]:[]),...guide.suggestions].map(term=>`<option value="${esc(term)}"></option>`).join('');});

document.addEventListener('change',event=>{if(!event.target.matches('input[name="marks"]'))return;document.querySelectorAll(`[data-mark="${event.target.value}"]`).forEach(pin=>{pin.classList.toggle('marked',event.target.checked);pin.setAttribute('aria-pressed',String(event.target.checked));});});
